import { answer, field as f, fixture as r, hints as h, option as o, quantity as q } from "../casework";
import type { CaseDraft, Casework } from "../casework";

/** Shared by the peak-shift preview and its prediction. */
function peakQueue({ retry, unknown, human }: CaseDraft) {
  const recoveries = Number(retry) ? 24 : 0;
  const staff = (unknown === "Staff + attempts" ? 48 - recoveries : 0) + (human === "Staff + attempts" ? 12 : 0);
  return { recoveries, staff, minutes: staff * 3, cost: 120 * 2 + Number(retry) * 32 * 2 };
}

const rushSpend = (live: number) => live * 5 + (52 - live) * 2;

